using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Drawing;using System.Reflection;using System.Windows.Forms;using MP1SkinStudio;
class ChoiceProbe{[STAThread]static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var f=new Form()){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);var choice=new ChoiceBox{Width=220,Height=28};f.Controls.Add(choice);choice.Items.AddRange(new SkinProject(args[0]).Pages().Cast<object>());choice.SelectedIndex=5;f.Show();Application.DoEvents();for(int n=0;n<3;n++){var sw=Stopwatch.StartNew();var menu=(StudioMenu)typeof(ChoiceBox).GetMethod("OpenChoicesForTest",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(choice,null);sw.Stop();Console.WriteLine("Open "+(n+1)+": "+sw.ElapsedMilliseconds+" ms; "+menu.Items.Count+" items; checked="+menu.Items.Cast<ToolStripMenuItem>().Count(i=>i.Checked));Console.Out.Flush();menu.Close();}f.Close();}return 0;}}
